import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadNunito = makeLoadFont('Nunito');

// Module-level font loading — handles delayRender internally
const { fontFamily: nunitoFamily } = loadNunito();



export type ZoomAnimationProps = Record<string, any>;

const ZoomAnimation: React.FC<ZoomAnimationProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 8,
  logoColor = "#2D8CFF",
  pulseColor = "#2D8CFF",
  pulseCount = 3,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Intro Animation Sequences
  const logoScale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const cameraScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, mass: 0.6 },
  });

  const textY = interpolate(
    spring({
      frame: frame - 20,
      fps,
      config: { damping: 14, mass: 0.8 },
    }),
    [0, 1],
    [60, 0]
  );

  const textOpacity = interpolate(frame - 20, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Layout calculations
  const centerYOffset = -60; // Shift up slightly to balance the text below
  const logoSize = 480;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Background Pulsing Rings */}
      {Array.from({ length: pulseCount }).map((_, i) => {
        const period = fps * 2.5; // Smooth, slow pulse duration
        const offset = (period / pulseCount) * i;
        const ringStartFrame = 30 + offset;

        // Hide ring completely before its start frame
        if (frame < ringStartFrame) return null;

        const loopFrame = (frame - ringStartFrame) % period;
        
        const ringScale = interpolate(loopFrame, [0, period], [1, 2.8], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        
        const ringOpacity = interpolate(
          loopFrame,
          [0, period * 0.1, period * 0.7, period],
          [0, 0.35, 0, 0],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }
        );

        return (
          <AbsoluteFill
            key={`pulse-ring-${i}`}
            style={{
              justifyContent: "center",
              alignItems: "center",
              top: centerYOffset,
            }}
          >
            <div
              style={{
                width: logoSize,
                height: logoSize,
                borderRadius: "50%",
                backgroundColor: pulseColor,
                transform: `scale(${ringScale})`,
                opacity: ringOpacity,
                position: "absolute",
                transition: "none",
              }}
            />
          </AbsoluteFill>
        );
      })}

      {/* Main Logo */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          top: centerYOffset,
        }}
      >
        <div
          style={{
            transform: `scale(${Math.max(0, logoScale)})`,
            transition: "none",
            position: "relative",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            width: logoSize,
            height: logoSize,
            borderRadius: "50%",
            backgroundColor: logoColor,
            border: "14px solid white",
            boxShadow: "0 0 0 3px #E5E5E5", // Simulates the faint outer grey ring
          }}
        >
          {/* Camera Icon */}
          <div
            style={{
              transform: `scale(${Math.max(0, cameraScale)})`,
              transition: "none",
            }}
          >
            <svg viewBox="0 0 310 200" width="250" height="161">
              {/* Camera Body */}
              <rect x="10" y="30" width="180" height="140" rx="35" fill="white" />
              {/* Camera Lens - Uses polygon with rounded stroke for perfect attachment geometry */}
              <polygon
                points="170,70 280,45 280,155 170,130"
                fill="white"
                stroke="white"
                strokeWidth="20"
                strokeLinejoin="round"
              />
            </svg>
          </div>
        </div>
      </AbsoluteFill>

      {/* Logotype ("zoom" text) */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          top: centerYOffset + 380, // Positioned precisely below the logo
        }}
      >
        <div
          style={{
            transform: `translateY(${textY}px)`,
            opacity: textOpacity,
            transition: "none",
          }}
        >
          <span
            style={{
              fontFamily: nunitoFamily,
              fontSize: 240,
              fontWeight: 800,
              color: logoColor,
              letterSpacing: "-0.07em",
              lineHeight: 1,
            }}
          >
            zoom
          </span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ZoomAnimation;